use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/phase-search-c7a178";
const PRIOR:&str="/home/ubuntu/src/zopro-perf-work/phase-search178/proof-sha256-after-diagnostic.json";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap()}
fn map(p:&str,local:bool)->PathBuf{let r=Path::new(R);for (prefix,dest)in[("/output/",if local{"local-output"}else{"remote-results/output"}),("/usr/local/bin/","context"),("/cr-basis/","context/basis"),("/fixtures/","context/fixtures"),("/cr/","context")]{if let Some(s)=p.strip_prefix(prefix){return r.join(dest).join(s)}}panic!("unmapped {p}")}
fn median(mut xs:Vec<f64>)->f64{assert!(xs.len()%2==1);xs.sort_by(f64::total_cmp);xs[xs.len()/2]}
fn main(){let mode=std::env::args().nth(1).unwrap();assert!(mode=="local"||mode=="remote");let local=mode=="local";let r=Path::new(R);let dir=r.join(if local{"local-output/preflight"}else{"remote-results/output/measure"});let complete=read(dir.join("complete.json"));assert_eq!(complete["status"],"complete");let count=if local{4}else{120};assert_eq!(complete["distinct_gnark_exports"],count);assert_eq!(complete["sdk_requests"],if local{16}else{16680});
let seed=if local{PathBuf::from(PRIOR)}else{r.join("proof-sha256-after-preflight.json")};if local{assert_eq!(hash(&seed),"b015c16fdf71d7caee67a6bc055d66368fe79b01a299c397e9408f94c36b312a");}
let mut ledger:BTreeSet<String>=serde_json::from_value(read(&seed)).unwrap();assert_eq!(ledger.len(),if local{55024}else{55028});let before=ledger.len();
let manifest=read(r.join("context/manifest.json"));for(p,h)in read(dir.join("pins.json")).as_object().unwrap(){assert_eq!(hash(map(p,local)),h.as_str().unwrap(),"{p}");}
let identities=read(dir.join("backings-before.json"));assert_eq!(identities,read(dir.join("backings-after.json")));assert_eq!(identities.as_array().unwrap().len(),6);let mut inodes=BTreeSet::new();for b in identities.as_array().unwrap(){assert!(inodes.insert((b["dev"].as_u64().unwrap(),b["inode"].as_u64().unwrap())));let p=b["path"].as_str().unwrap();assert_eq!(b["sha256"],manifest["container_pins"][p]);}
let plan=read(dir.join("plan.json"));let jobs=read(dir.join("jobs.json"));assert_eq!(jobs.as_array().unwrap().len(),count);assert_eq!(plan["steps"].as_array().unwrap().len(),2*count);let run=read(dir.join("workflow/result.json"));assert_eq!(run["status"],"complete");assert_eq!(run["steps"],json!(plan["steps"].as_array().unwrap().iter().map(|s|s["name"].as_str().unwrap()).collect::<Vec<_>>()));
for step in plan["steps"].as_array().unwrap(){let d=dir.join("workflow").join(step["name"].as_str().unwrap());let exit=read(d.join("exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{stream}.log"))),exit[format!("{stream}_sha256")]);}let command=read(d.join("command.json"));assert_eq!(&command["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());assert_eq!(command["environment"],step["environment"]);}
let mut expected=BTreeSet::new();if local{for shape in["1x2","2x2"]{expected.insert((shape.to_string(),4,"ON".to_string(),"preflight".to_string(),0));}for arm in["OFF","REF"]{expected.insert(("1x2".to_string(),4,arm.to_string(),"preflight".to_string(),0));}}else{for shape in["1x2","2x2"]{for w in[32,96]{for arm in["REF","OFF","ON"]{expected.insert((shape.to_string(),w,arm.to_string(),"preflight".to_string(),0));for block in 0..9{expected.insert((shape.to_string(),w,arm.to_string(),"latency".to_string(),block));}}}}}
let producer=read(dir.join("rows.json"));let mut rows=vec![];let mut timed=0;let mut capture_seconds=0.;let mut verify_seconds=0.;
for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let shape=j["case"]["shape"].as_str().unwrap();let arm=j["arm"].as_str().unwrap();let workers=j["workers"].as_u64().unwrap();let block=j["block"].as_u64().unwrap();let panel=j["panel"].as_str().unwrap();assert!(expected.remove(&(shape.to_string(),workers,arm.to_string(),panel.to_string(),block)));let rounds=if panel=="latency"{151}else{1};assert_eq!(j["rounds"],rounds);assert_eq!(j["backing"],block%3);
let step=plan["steps"].as_array().unwrap().iter().find(|s|s["name"]==name).unwrap();let binary=format!("/usr/local/bin/{}{}",if arm=="REF"{"cr-previous"}else{"cr-current"},block%3);assert_eq!(j["binary"],binary);let affinity=format!("0-{}",workers-1);let proof=j["proof_dir"].as_str().unwrap();assert_eq!(step["argv"],json!(["/usr/bin/taskset","-c",affinity,binary,j["case"]["image"],j["case"]["request"],rounds.to_string(),proof]));
let mut env=manifest["environment"].clone();env["ZOPRO_BASIS_KEY_DIR"]="/cr-basis".into();env["ZOPRO_CPU_LAGRANGE_DIR"]="/output/lagrange-cache".into();env["ZOPRO_CPU_DEDUP"]="1".into();env["RAYON_NUM_THREADS"]=workers.to_string().into();env["ZOPRO_CPU_INDEXED_TILE_BUNDLES"]="1".into();if arm!="REF"{env["ZOPRO_DIAGNOSTIC_SEARCH_DIVISOR"]=if arm=="ON"{"3"}else{"0"}.into();}assert_eq!(step["environment"],env);
let c=manifest["cases"].as_array().unwrap().iter().find(|c|c["shape"]==shape).unwrap();for field in["image","request","image_sha256","public_sha256"]{assert_eq!(j["case"][field],c[field]);}
let d=dir.join("workflow").join(name);capture_seconds+=read(d.join("exit.json"))["elapsed_ms"].as_f64().unwrap()/1000.;let raw=fs::read_to_string(d.join("stdout.log")).unwrap();let samples=raw.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).enumerate().map(|(i,l)|{let v:Value=serde_json::from_str(l).unwrap();assert_eq!(v["round"],i);let ns=v["ns"].as_u64().unwrap_or_else(||(v["ms"].as_f64().unwrap()*1e6).round()as u64);assert!(ns>0);ns}).collect::<Vec<_>>();assert_eq!(samples.len()as u64,rounds);timed+=rounds;let mean=samples.iter().map(|&n|n as u128).sum::<u128>()as f64/samples.len()as f64;let p=producer.as_array().unwrap().iter().find(|p|p["job"]["name"]==name).unwrap();assert!((p["mean_ns"].as_f64().unwrap()-mean).abs()<1e-6);
let summaries=raw.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).collect::<Vec<_>>();assert_eq!(summaries.len(),1);let s:Value=serde_json::from_str(summaries[0]).unwrap();assert_eq!(s["priming"],3);assert_eq!(s["rounds"],rounds);assert_eq!(s["workers"],workers);assert_eq!(s["indexed_entries"],4*rounds);if arm!="REF"{assert_eq!(s["search_scopes"],if arm=="ON"{rounds}else{0});assert_eq!(s["search_restored"],true);}assert_eq!(s["placement_before"],s["placement_after"]);let placement=&s["placement_before"];assert_eq!(placement["mode"],"fixed");assert_eq!(placement["tasks"],workers+1);assert_eq!(placement["main_allowed"],json!((0..workers).collect::<Vec<_>>()));assert_eq!(placement["worker_rows"].as_array().unwrap().len()as u64,workers);for(i,w)in placement["worker_rows"].as_array().unwrap().iter().enumerate(){assert_eq!(w["index"],i);assert_eq!(w["allowed"],json!([i]));}
let proof=map(proof,local);assert_eq!(fs::metadata(proof.join("0.proof")).unwrap().len(),164);let ph=hash(proof.join("0.proof"));assert!(ledger.insert(ph.clone()));let public=hash(proof.join("0.public"));assert_eq!(public,c["public_sha256"]);let vn=format!("verify-{name}");let vd=dir.join("workflow").join(&vn);verify_seconds+=read(vd.join("exit.json"))["elapsed_ms"].as_f64().unwrap()/1000.;let vs=plan["steps"].as_array().unwrap().iter().find(|s|s["name"]==vn).unwrap();assert_eq!(vs["argv"],json!(["/usr/local/bin/interval-verify",c["image"],c["image_sha256"],format!("{}/0.proof",j["proof_dir"].as_str().unwrap()),format!("{}/0.public",j["proof_dir"].as_str().unwrap()),c["public_sha256"]]));let verified=fs::read_to_string(vd.join("stdout.log")).unwrap();assert_eq!(verified.lines().filter(|l|l.starts_with("VERIFIED ")).count(),1);for binding in[format!("proof_sha256={ph}"),format!("public_sha256={public}"),format!("image_sha256={}",c["image_sha256"].as_str().unwrap())]{assert!(verified.contains(&binding));}
rows.push(json!({"name":name,"shape":shape,"workers":workers,"arm":arm,"block":block,"backing":block%3,"panel":panel,"ms":mean/1e6,"cpu_ms":(s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap())/rounds as f64,"rss_mib":s["whole_process_maxrss_kib"].as_f64().unwrap()/1024.,"summary":s}));}
assert!(expected.is_empty());assert_eq!(timed,if local{4}else{16320});assert_eq!(ledger.len(),if local{55028}else{55148});assert_eq!(complete["proof_ledger"],ledger.len());
let ledgername=if local{"proof-sha256-after-preflight.json"}else{"proof-sha256-after-capture.json"};save(r.join(ledgername),json!(ledger));save(r.join(format!("{mode}-rows.json")),json!(rows));let review=json!({"passed":true,"phase":mode,"processes":count,"SDK_calls_including_primes":timed+count as u64*3,"timed_samples":timed,"new_Gnark_exports":ledger.len()-before,"canonical_count":ledger.len(),"canonical_sha256":hash(r.join(ledgername)),"capture_seconds":capture_seconds,"verifier_seconds":verify_seconds,"requires_transport_verification_for_remote":!local});save(r.join(format!("{mode}-review.json")),review.clone());println!("{review}");
if !local{let mut checks=vec![];let mut summaries=vec![];for shape in["1x2","2x2"]{for w in[32,96]{let selected=rows.iter().filter(|x|x["panel"]=="latency"&&x["shape"]==shape&&x["workers"]==w).collect::<Vec<_>>();assert_eq!(selected.len(),27);let mut arms=vec![];for arm in["REF","OFF","ON"]{let values=selected.iter().filter(|x|x["arm"]==arm).collect::<Vec<_>>();assert_eq!(values.len(),9);arms.push(json!({"arm":arm,"ms":median(values.iter().map(|x|x["ms"].as_f64().unwrap()).collect()),"cpu_ms":median(values.iter().map(|x|x["cpu_ms"].as_f64().unwrap()).collect()),"max_rss_mib":values.iter().map(|x|x["rss_mib"].as_f64().unwrap()).reduce(f64::max).unwrap()}));}
for control in["OFF","REF"]{for backing in 0..3{let mut ratios=vec![];for block in (backing..9).step_by(3){let row=|arm:&str|selected.iter().find(|x|x["arm"]==arm&&x["block"]==block).unwrap();ratios.push(row("ON")["ms"].as_f64().unwrap()/row(control)["ms"].as_f64().unwrap());}let ratio=median(ratios);let gain=shape=="1x2"&&w==96;checks.push(json!({"shape":shape,"workers":w,"comparison":format!("ON/{control}"),"backing":backing,"ratio":ratio,"gain_required":gain,"passed":if gain{ratio<1.}else{ratio<=1.03}}));}}
let rss=|arm:&str|arms.iter().find(|a|a["arm"]==arm).unwrap()["max_rss_mib"].as_f64().unwrap();checks.push(json!({"shape":shape,"workers":w,"kind":"rss","passed":rss("ON")<=rss("REF")*1.05+1.}));summaries.push(json!({"shape":shape,"workers":w,"arms":arms}));}}
save(r.join("target-analysis.json"),json!({"passed":checks.iter().all(|c|c["passed"]==true),"checks":checks,"summary":summaries,"screen_only":true}));}
}
